export class Oauth {
  /**
   * Register
   *
   * An app registers itself (RFC 7591), without signing in: it gets a `client_id`, and a `client_secret` if it
   * asked for one. It can do nothing until someone gives it access. Audited as `oauth.client.register`.
   */
  public static register<ThrowOnError extends boolean = false>(
    options: Options<RegisterData, ThrowOnError>,
  ): RequestResult<RegisterResponses, RegisterErrors, ThrowOnError> {
    return (options.client ?? client).post<RegisterResponses, RegisterErrors, ThrowOnError>({
      url: "/api/v1/oauth/register",
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...options.headers,
      },
    });
  }

  /**
   * Consent
   *
   * What the consent page shows for an app's request: the app, where it takes you back to and what it asks for.
   * 400 when the request can't be answered (an unknown app, an address it didn't register, no PKCE challenge).
   */
  public static consent<ThrowOnError extends boolean = false>(
    options: Options<ConsentData, ThrowOnError>,
  ): RequestResult<ConsentResponses, ConsentErrors, ThrowOnError> {
    return (options.client ?? client).get<ConsentResponses, ConsentErrors, ThrowOnError>({
      url: "/api/v1/oauth/authorize",
      ...options,
    });
  }

  /**
   * Answer
   *
   * Your answer to an app's request. Yes gives it a one-time code (five minutes) at its redirect address, which
   * it swaps for tokens that act as you, with your roles; no sends it `error=access_denied`. Audited as
   * `oauth.grant`.
   */
  public static answer<ThrowOnError extends boolean = false>(
    options: Options<AnswerData, ThrowOnError>,
  ): RequestResult<AnswerResponses, AnswerErrors, ThrowOnError> {
    return (options.client ?? client).post<AnswerResponses, AnswerErrors, ThrowOnError>({
      url: "/api/v1/oauth/authorize",
      ...options,
      headers: {
        "Content-Type": "application/json",
        ...options.headers,
      },
    });
  }

  /**
   * Token
   *
   * The app swaps its code (`grant_type=authorization_code`, with `code_verifier` and the same `redirect_uri`)
   * or its refresh token (`grant_type=refresh_token`) for an access token and a new refresh token. Form-encoded, as
   * OAuth has it; errors are `{error, error_description}`.
   */
  public static token<ThrowOnError extends boolean = false>(
    options: Options<TokenData, ThrowOnError>,
  ): RequestResult<TokenResponses, TokenErrors, ThrowOnError> {
    return (options.client ?? client).post<TokenResponses, TokenErrors, ThrowOnError>({
      ...urlSearchParamsBodySerializer,
      url: "/api/v1/oauth/token",
      ...options,
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        ...options.headers,
      },
    });
  }

  /**
   * Revoke
   *
   * An app hands back a token, access or refresh (RFC 7009): the access it was given ends. Answers the same
   * whether or not the token was known. Audited as `oauth.revoke`.
   */
  public static revoke<ThrowOnError extends boolean = false>(
    options: Options<RevokeData, ThrowOnError>,
  ): RequestResult<RevokeResponses, RevokeErrors, ThrowOnError> {
    return (options.client ?? client).post<RevokeResponses, RevokeErrors, ThrowOnError>({
      ...urlSearchParamsBodySerializer,
      url: "/api/v1/oauth/revoke",
      ...options,
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        ...options.headers,
      },
    });
  }

  /**
   * List Grants
   *
   * The apps you gave access to, the latest first.
   */
  public static listGrants<ThrowOnError extends boolean = false>(
    options?: Options<ListGrantsData, ThrowOnError>,
  ): RequestResult<ListGrantsResponses, unknown, ThrowOnError> {
    return (options?.client ?? client).get<ListGrantsResponses, unknown, ThrowOnError>({
      url: "/api/v1/oauth/grants",
      ...options,
    });
  }

  /**
   * Revoke Grant
   *
   * Take an app's access away: its tokens stop working now. Audited as `oauth.revoke`.
   */
  public static revokeGrant<ThrowOnError extends boolean = false>(
    options: Options<RevokeGrantData, ThrowOnError>,
  ): RequestResult<RevokeGrantResponses, RevokeGrantErrors, ThrowOnError> {
    return (options.client ?? client).delete<RevokeGrantResponses, RevokeGrantErrors, ThrowOnError>({
      url: "/api/v1/oauth/grants/{grant_id}",
      ...options,
    });
  }
}

